        vignette: CFG_pickBool(src, 'vignette', CFG_DEFAULTS.vignette),
        glitch: CFG_pickBool(src, 'glitch', CFG_DEFAULTS.glitch),
        hud: CFG_pickBool(src, 'hud', CFG_DEFAULTS.hud),
